mapper.select:
/* CastUserSnapshotMapper.retrieveNextRsrcNo */
SELECT LPAD(PMOWN.SQ1_TN_PM_SMLT_USER_RSRC.NEXTVAL, 3, '0') AS RSRC_NO
FROM DUAL

mapper.insert:
/* CastUserSnapshotMapper.insertRsrcMstr */
INSERT INTO PMOWN.${mstrTableNm} (
    ${mstrIdColumnNm}, ${mstrNmColumnNm}, PRCS_STTS_CD, CFMTN_YN, USE_YN,
    FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT
) VALUES (
    #{snapshot.rsrcNo},
    '사용자 시뮬레이션 ' || #{snapshot.smltId},
    '99', 'Y', 'Y',
    #{snapshot.loginUserId}, #{snapshot.loginIpAddr}, CURRENT_TIMESTAMP
)

/* CastUserSnapshotMapper.insertScrtyCntrlAtrb */ INSERT INTO PMOWN.TN_PM_SMLT_FCLTY_OPNG_SCRTY_CNTRL_ATRB ( SCRTY_CNTRL_ATRB_ID, FCLTY_OPNG_SN, TMNL_ID, FCLT_SE_CD, GATE_NO, FCLTY_CNT, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT ) SELECT #{rsrcNo}, ROW_NUMBER() OVER (ORDER BY X.TMNL_ID, X.DPTGT_NO, X.OPER_BGNG_HOUR), X.TMNL_ID, 'D', X.DPTGT_NO, X.SCSH_CNTOM, #{loginUserId}, #{loginIpAddr}, CURRENT_TIMESTAMP FROM ( SELECT P.TMNL_ID, P.DPTGT_NO, P.OPER_BGNG_HOUR, NVL(P.SCSH_CNTOM, 0) AS SCSH_CNTOM FROM PMOWN.TN_PM_SMLT_SCSH_OPER_PLAN P WHERE P.SMLT_ID = #{smltId}
UNION ALL
SELECT D.TMNL_ID, D.DPTGT_NO, 0 AS OPER_BGNG_HOUR, NVL(D.SCSH_CNTOM, 0) AS SCSH_CNTOM FROM PMOWN.TN_PM_SMLT_USER_DPTGT D WHERE D.SMLT_ID = #{smltId} AND D.OPER_YN = 'Y' AND NOT EXISTS ( SELECT 1 FROM PMOWN.TN_PM_SMLT_SCSH_OPER_PLAN P WHERE P.SMLT_ID = D.SMLT_ID AND P.TMNL_ID = D.TMNL_ID AND P.DPTGT_NO = D.DPTGT_NO ) ) X
